package leetcode.medium;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import java.util.Arrays;

public class OnlineStockSpanTest {

    @Test
    public void calculateSpans_EmptyArray_ReturnsEmptyArray() {
        int[] prices = {};
        int[] result = new OnlineStockSpan().calculateSpans(prices);
        assert Arrays.equals(result, new int[0]);
    }

    @Test
    public void calculateSpans_SingleElementReturnOneSpan() {
        int[] prices = {1};
        int[] result = new OnlineStockSpan().calculateSpans(prices);
        assertEquals(new int[]{1}, result);
    }

    @Test
    public void calculateSpans_MultipleElements_ReturnsCorrectSpans() {
        int[] prices = {10, 7, 5, 8, 11, 9};
        int[] expected = {2, 4, 3, 4, 5, 6};
        int[] result = new OnlineStockSpan().calculateSpans(prices);
        assert Arrays.equals(expected, result);
    }

    @Test
    public void next_OnlyPriceIncreases_ReturnsIncreasingSequence() {
        int[] prices = {10, 9, 8, 7, 6};
        for (int i = 0; i < prices.length - 1; i++) {
            assertEquals(i + 1, new OnlineStockSpan().next(prices[i]));
        }
    }

    @Test
    public void next_SinglePriceStaySame_ReturnsOne() {
        int[] prices = {10};
        assertEquals(1, new OnlineStockSpan().next(prices[0]));
    }

    @Test
    public void next_PriceIncreasesThenDecreases_ReturnsCorrectSequence() {
        int[] prices = {10, 9, 8, 7, 6, 5, 4};
        for (int i = 1; i < prices.length; i++) {
            if (prices[i - 1] > prices[i]) {
                assertEquals(i + 1, new OnlineStockSpan().next(prices[i]));
            } else if (prices[i - 1] < prices[i]) {
                assertEquals(1, new OnlineStockSpan().next(prices[i]));
            }
        }
    }

}

